    await f.run();
    assert.deepEqual(f.trace, [...observations.map(() => 'read'), 'scroll', 'focus', 'insert', 'submit']);
    assert.deepEqual(f.budgets, [30_000]); assert.equal(f.reads(), observations.length);
  }
